//! Temporary configured-ICC production-command probe; removed after verification.
use photocraft_cms::{Builtin, Curve, Intent, Profile, Transform};
use photocraft_engine::{EngineError, Session};
use serde_json::json;
fn main() -> Result<(), Box<dyn std::error::Error>> {
    let mut cases = Vec::new();
    for (mode, builtin) in [("rgb", Builtin::DisplayP3), ("gray", Builtin::GrayGamma22)] {
        let mut profile = builtin.profile().clone();
        profile.white_point = [0.79, 0.83, 0.68];
        let curve = Curve::Table(vec![0.05, 0.12, 0.4, 1.0]);
        if mode == "gray" {
            profile.gray_trc = Some(curve);
        } else {
            profile.trc = Some(std::array::from_fn(|_| curve.clone()));
        }
        let bytes = profile.with_encoded_bytes().to_bytes();
        let source = Profile::parse(&bytes)?;
        for (intent, bpc) in [(Intent::RelativeColorimetric, false), (Intent::AbsoluteColorimetric, true)] {
            let mut session = Session::new();
            session.execute("file.new", json!({"width":257,"height":65,"depth":32,"mode":mode,"background":"transparent"}))?;
            session.edit("fixture", |doc, _| {
                let bounds = doc.bounds();
                let surface = doc.layers.first_mut().and_then(|l| l.surface_mut()).ok_or_else(|| EngineError::Other("fixture has no surface".into()))?;
                let format = surface.format();
                let mut data = Vec::new();
                for _ in bounds.y0..bounds.y1 {
                    for x in bounds.x0..bounds.x1 {
                        let pixel = if x % 2 == 0 { [0.12, 0.29, 0.57, 1.0] } else { [0.43, 0.39, 0.2, 1.0] };
                        data.extend(photocraft_raster::from_rgba(&format, pixel));
                    }
                }
                surface.write_region(bounds, &data);
                doc.icc_profile = Some(bytes.clone());
                Ok(())
            })?;
            session.execute("edit.colorSettings", json!({"intent":intent.id(),"bpc":bpc}))?;
            let reference = Transform::new(&source, Builtin::Srgb.profile(), intent, bpc)?;
            let mut expected = Vec::new();
            let before = session.active().ok_or("missing fixture")?;
            let surface = before.doc.layers.first().and_then(|l| l.surface()).ok_or("missing fixture surface")?;
            for x in 0..2 {
                let pixel = surface.rgba(x, 0);
                let mut out = [0.0f32; 16];
                reference.eval(if mode == "gray" { &pixel[..1] } else { &pixel[..3] }, &mut out);
                expected.push([0, 1, 2].map(|i| (out[i].clamp(0.0, 1.0) * 255.0).round() as u8));
            }
            session.execute("image.mode.indexedColor", json!({"palette":"exact","forced":"none","dither":"none"}))?;
            let after = session.active().ok_or("missing result")?;
            let table = after.doc.color_table.as_ref().ok_or("missing color table")?;
            let pass = expected.iter().all(|color| table.colors.contains(color));
            cases.push(json!({"mode":mode,"intent":intent.id(),"bpc":bpc,"expected":expected,"actual":table.colors,"pass":pass}));
        }
    }
    println!("{}", json!({"cases":cases}));
    Ok(())
}
